import { setProjectAnnotations } from '@storybook/react-vite';
import * as previewAnnotations from './preview.js';

export const annotations = setProjectAnnotations([previewAnnotations]);

import '@testing-library/jest-dom/vitest';

// jsdom ships neither of these. A real browser has both, so these shims install
// only when the API is genuinely missing and browser mode exercises the real
// implementations instead.
if (typeof globalThis.ResizeObserver === 'undefined') {
	globalThis.ResizeObserver = class ResizeObserver {
		observe() {}
		unobserve() {}
		disconnect() {}
	};
}

if (typeof Element !== 'undefined' && typeof Element.prototype.scrollIntoView !== 'function') {
	Element.prototype.scrollIntoView = () => {};
}

import { Search } from '@signozhq/icons';
import { Button, Input } from '@signozhq/ui';
import { useState } from 'react';
import styles from './TokenSearch.module.css';

interface TokenSearchProps {
	onSearch: (query: string) => void;
	onCategoryFilter?: (category: string | null) => void;
	categories?: string[];
	selectedCategory?: string | null;
}

export function TokenSearch({
	onSearch,
	onCategoryFilter,
	categories,
	selectedCategory,
}: TokenSearchProps) {
	const [query, setQuery] = useState('');

	const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
		const value = e.target.value;
		setQuery(value);
		onSearch(value);
	};

	return (
		<div className={styles.container}>
			<div className={styles.searchWrapper}>
				<Input
					type="text"
					value={query}
					onChange={handleSearchChange}
					placeholder="Search tokens..."
					prefix={<Search />}
				/>
			</div>

			{onCategoryFilter && categories && categories.length > 0 && (
				<div className={styles.categoryFilters}>
					<Button
						type="button"
						onClick={() => onCategoryFilter(null)}
						{...(selectedCategory === null
							? { variant: 'solid', color: 'primary' }
							: { variant: 'outlined', color: 'secondary' })}
						size="md"
					>
						All
					</Button>
					{categories.map((category) => (
						<Button
							key={category}
							type="button"
							onClick={() => onCategoryFilter(category)}
							{...(selectedCategory === category
								? { variant: 'solid', color: 'primary' }
								: { variant: 'outlined', color: 'secondary' })}
							size="md"
						>
							{category}
						</Button>
					))}
				</div>
			)}
		</div>
	);
}

import Spacing from '../components/Spacing.jsx';

export default {
	title: 'Design System/Spacing',
	component: Spacing,
	parameters: {
		layout: 'fullscreen',
		backgrounds: {
			default: 'dark',
			values: [{ name: 'dark', value: '#000' }],
		},
	},
};

export const SpacingScale = () => <Spacing />;

import { Typography } from '@signozhq/ui';
import { getTransformedSpacingTokens } from '../utils.js';
import styles from './Spacing.module.css';

const spacing = getTransformedSpacingTokens();
const spacingKeys = Object.keys(spacing);

function Spacing() {
	return (
		<div className={styles.container}>
			<Typography size="lg" weight="bold" className={styles.title}>
				Spacing Scale
			</Typography>

			{spacingKeys.map((size) => {
				const value = spacing[size as keyof typeof spacing];

				return (
					<div key={size} className={styles.spacingItem}>
						<Typography size="sm">
							{size} - {value}
						</Typography>
						<div className={styles.spacingBar} style={{ width: value }}></div>
					</div>
				);
			})}
		</div>
	);
}

export default Spacing;

import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it, vi } from 'vitest';
import { Button } from '../button.js';

describe('Button pointer interaction', () => {
	it('calls onClick with the button as the event target', async () => {
		const user = userEvent.setup();
		const onClick = vi.fn();
		render(
			<Button size="md" variant="solid" color="primary" onClick={onClick}>
				Click me
			</Button>,
		);

		const button = screen.getByRole('button');
		await user.click(button);

		expect(onClick).toHaveBeenCalledTimes(1);
		expect(onClick.mock.calls[0]?.[0].target).toBe(button);
	});

	it('calls onClick once per click', async () => {
		const user = userEvent.setup();
		const onClick = vi.fn();
		render(
			<Button size="md" variant="solid" color="primary" onClick={onClick}>
				Click me
			</Button>,
		);

		const button = screen.getByRole('button');
		await user.click(button);
		await user.click(button);
		await user.click(button);

		expect(onClick).toHaveBeenCalledTimes(3);
	});

	it('calls onDoubleClick once and onClick twice on a double click', async () => {
		const user = userEvent.setup();
		const onClick = vi.fn();
		const onDoubleClick = vi.fn();
		render(
			<Button
				size="md"
				variant="solid"
				color="primary"
				onClick={onClick}
				onDoubleClick={onDoubleClick}
			>
				Double
			</Button>,
		);

		await user.dblClick(screen.getByRole('button'));

		expect(onDoubleClick).toHaveBeenCalledTimes(1);
		expect(onClick).toHaveBeenCalledTimes(2);
	});

	it('does not activate on hover alone', async () => {
		const user = userEvent.setup();
		const onClick = vi.fn();
		render(
			<Button size="md" variant="solid" color="primary" onClick={onClick}>
				Hover me
			</Button>,
		);

		await user.hover(screen.getByRole('button'));

		expect(onClick).not.toHaveBeenCalled();
	});
});

describe('Button keyboard interaction', () => {
	it('activates on Enter', async () => {
		const user = userEvent.setup();
		const onClick = vi.fn();
		render(
			<Button size="md" variant="solid" color="primary" onClick={onClick}>
				Save
			</Button>,
		);

		screen.getByRole('button').focus();
		await user.keyboard('{Enter}');

		expect(onClick).toHaveBeenCalledTimes(1);
	});

	it('activates on Space', async () => {
		const user = userEvent.setup();
		const onClick = vi.fn();
		render(
			<Button size="md" variant="solid" color="primary" onClick={onClick}>
				Save
			</Button>,
		);

		screen.getByRole('button').focus();
		await user.keyboard('[Space]');

		expect(onClick).toHaveBeenCalledTimes(1);
	});

	it('forwards onKeyDown and onKeyUp with the pressed key', async () => {
		const user = userEvent.setup();
		const onKeyDown = vi.fn();
		const onKeyUp = vi.fn();
		render(
			<Button size="md" variant="solid" color="primary" onKeyDown={onKeyDown} onKeyUp={onKeyUp}>
				Save
			</Button>,
		);

		screen.getByRole('button').focus();
		await user.keyboard('{Escape}');

		expect(onKeyDown).toHaveBeenCalledTimes(1);
		expect(onKeyDown.mock.calls[0]?.[0].key).toBe('Escape');
		expect(onKeyUp).toHaveBeenCalledTimes(1);
	});
});

describe('Button focus', () => {
	it('is reachable by Tab', async () => {
		const user = userEvent.setup();
		render(
			<Button size="md" variant="solid" color="primary">
				Save
			</Button>,
		);

		await user.tab();

		expect(screen.getByRole('button')).toHaveFocus();
	});

	it('is skipped by Tab when tabIndex is -1', async () => {
		const user = userEvent.setup();
		render(
			<>
				<Button size="md" variant="solid" color="primary" tabIndex={-1}>
					Skipped
				</Button>
				<input data-testid="input" />
			</>,
		);

		await user.tab();

		expect(screen.getByTestId('input')).toHaveFocus();
	});

	it('takes focus on mount with autoFocus', () => {
		render(
			// eslint-disable-next-line jsx-a11y/no-autofocus -- the prop is what this test covers
			<Button size="md" variant="solid" color="primary" autoFocus>
				Save
			</Button>,
		);

		expect(screen.getByRole('button')).toHaveFocus();
	});
});

import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it, vi } from 'vitest';

import { Callout } from '../callout.js';

const icon = <svg />;

describe('Callout.Action', () => {
	it('renders the action after the description and leaves its click to it', async () => {
		const user = userEvent.setup();
		const onRefresh = vi.fn();
		render(
			<Callout.Action
				color="warning"
				size="sm"
				icon={icon}
				testId="c"
				action={
					<button type="button" onClick={onRefresh}>
						Refresh
					</button>
				}
			>
				New data is available.
			</Callout.Action>,
		);

		const action = screen.getByTestId('c-action');
		expect(action).toHaveAttribute('data-slot', 'callout-action');
		expect(screen.getByTestId('c-description').compareDocumentPosition(action)).toBe(
			Node.DOCUMENT_POSITION_FOLLOWING,
		);

		await user.click(screen.getByRole('button', { name: 'Refresh' }));

		expect(onRefresh).toHaveBeenCalledOnce();
		expect(screen.getByTestId('c')).toBeInTheDocument();
	});

	it('keeps the live region role of its color', () => {
		render(
			<Callout.Action color="danger" size="sm" icon={icon} testId="c" action="Retry">
				The request failed.
			</Callout.Action>,
		);

		expect(screen.getByTestId('c')).toHaveAttribute('role', 'alert');
		expect(screen.getByRole('alert')).toContainElement(screen.getByTestId('c-action'));
	});

	it('renders nothing while the children are empty', () => {
		render(
			<Callout.Action color="warning" size="sm" icon={icon} testId="c" action="Refresh">
				{null}
			</Callout.Action>,
		);

		expect(screen.queryByTestId('c')).not.toBeInTheDocument();
	});

	it('leaves out the action box while the action is empty', () => {
		render(
			<Callout.Action color="warning" size="sm" icon={icon} testId="c" action={false}>
				a
			</Callout.Action>,
		);

		expect(screen.getByTestId('c')).toBeInTheDocument();
		expect(screen.queryByTestId('c-action')).not.toBeInTheDocument();
	});
});

