import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { useState } from 'react';
import { describe, expect, it, vi } from 'vitest';
import { Input } from '../input.js';

function ControlledInput() {
	const [value, setValue] = useState('');

	return (
		<Input
			aria-label="Organisation"
			value={value}
			onChange={(event) => setValue(event.target.value)}
		/>
	);
}

describe('Input interaction', () => {
	it('types into an uncontrolled input', async () => {
		const user = userEvent.setup();
		render(<Input aria-label="Organisation" defaultValue="Spring" />);

		const field = screen.getByRole('textbox');
		await user.type(field, 'field');

		expect(field).toHaveValue('Springfield');
	});

	it('types into a controlled input', async () => {
		const user = userEvent.setup();
		render(<ControlledInput />);

		const field = screen.getByRole('textbox');
		await user.type(field, 'Simpsonville');

		expect(field).toHaveValue('Simpsonville');
	});

	it('accepts a react-hook-form register() shaped spread', async () => {
		// The shape `register()` returns: optional callbacks and a ref, no `disabled` written.
		const registration: {
			name: string;
			onChange: (event: unknown) => Promise<boolean>;
			onBlur: (event: unknown) => Promise<boolean>;
			ref: (instance: HTMLInputElement | null) => void;
			disabled?: boolean;
		} = {
			name: 'organisation',
			onChange: vi.fn(async () => true),
			onBlur: vi.fn(async () => true),
			ref: vi.fn(),
		};
		const user = userEvent.setup();
		render(<Input aria-label="Organisation" {...registration} />);

		const field = screen.getByRole('textbox');
		await user.type(field, 'a');
		await user.tab();

		expect(field).toHaveAttribute('name', 'organisation');
		expect(registration.onChange).toHaveBeenCalled();
		expect(registration.onBlur).toHaveBeenCalled();
		expect(registration.ref).toHaveBeenCalledWith(field);
	});

	it('fires onWheel', () => {
		const onWheel = vi.fn();
		render(<Input aria-label="Count" onWheel={onWheel} />);

		screen.getByRole('textbox').dispatchEvent(new WheelEvent('wheel', { bubbles: true }));

		expect(onWheel).toHaveBeenCalledTimes(1);
	});

	it('blocks typing while disabled', async () => {
		const onChange = vi.fn();
		const user = userEvent.setup();
		render(
			<Input aria-label="Organisation" disabled disabledTooltip={undefined} onChange={onChange} />,
		);

		await user.keyboard('[Tab]');

		expect(screen.getByRole('textbox')).not.toHaveFocus();
		expect(onChange).not.toHaveBeenCalled();
	});

	it('keeps a read-only input focusable without accepting changes', async () => {
		const onChange = vi.fn();
		const user = userEvent.setup();
		render(
			<Input
				aria-label="Organisation"
				value="Springfield"
				onChange={onChange}
				readOnly
				readOnlyTooltip={undefined}
			/>,
		);

		const field = screen.getByRole('textbox');
		await user.tab();

		expect(field).toHaveFocus();

		await user.keyboard('x');

		expect(onChange).not.toHaveBeenCalled();
		expect(field).toHaveValue('Springfield');
	});

	it('submits on Enter inside a form', async () => {
		const onSubmit = vi.fn((event: { preventDefault(): void }) => event.preventDefault());
		const user = userEvent.setup();
		render(
			<form onSubmit={onSubmit}>
				<Input aria-label="Organisation" name="organisation" />
			</form>,
		);

		await user.type(screen.getByRole('textbox'), 'Springfield[Enter]');

		expect(onSubmit).toHaveBeenCalledTimes(1);
	});

	it('leaves a disabled input out of the form submit', () => {
		render(
			<form data-testid="form">
				<Input aria-label="Organisation" name="organisation" disabled disabledTooltip={undefined} />
			</form>,
		);

		const form = screen.getByTestId<HTMLFormElement>('form');

		expect(new FormData(form).has('organisation')).toBe(false);
	});
});

import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it } from 'vitest';
import { Tooltip } from '../presets/tooltip.js';
import { TooltipProvider } from '../subcomponents/tooltip-provider.js';

const TITLE = 'Helpful information';

describe('Tooltip pointer', () => {
	it('opens on hover', async () => {
		const user = userEvent.setup();
		render(
			<Tooltip title={TITLE}>
				<button type="button">Hover</button>
			</Tooltip>,
		);

		await user.hover(screen.getByRole('button'));

		expect(await screen.findByRole('tooltip')).toHaveTextContent(TITLE);
	});

	it('closes again when the pointer leaves', async () => {
		const user = userEvent.setup();
		render(
			<Tooltip title={TITLE}>
				<button type="button">Hover</button>
			</Tooltip>,
		);
		const trigger = screen.getByRole('button');

		await user.hover(trigger);
		expect(await screen.findByRole('tooltip')).toBeInTheDocument();

		await user.unhover(trigger);

		await waitFor(() => expect(screen.queryByRole('tooltip')).not.toBeInTheDocument());
	});

	it('puts nothing in the DOM before the first hover', () => {
		render(
			<Tooltip title={TITLE}>
				<button type="button">Hover</button>
			</Tooltip>,
		);

		expect(screen.queryByRole('tooltip')).not.toBeInTheDocument();
		expect(document.querySelector('[data-slot="tooltip-content"]')).toBeNull();
	});

	it('closes on Escape', async () => {
		const user = userEvent.setup();
		render(
			<Tooltip title={TITLE}>
				<button type="button">Hover</button>
			</Tooltip>,
		);

		await user.hover(screen.getByRole('button'));
		expect(await screen.findByRole('tooltip')).toBeInTheDocument();

		await user.keyboard('{Escape}');

		await waitFor(() => expect(screen.queryByRole('tooltip')).not.toBeInTheDocument());
	});
});

describe('Tooltip keyboard', () => {
	it('opens on focus', async () => {
		const user = userEvent.setup();
		render(
			<Tooltip title={TITLE}>
				<button type="button">Hover</button>
			</Tooltip>,
		);

		await user.tab();

		expect(screen.getByRole('button')).toHaveFocus();
		expect(await screen.findByRole('tooltip')).toHaveTextContent(TITLE);
	});

	it('closes again on blur', async () => {
		const user = userEvent.setup();
		render(
			<>
				<Tooltip title={TITLE}>
					<button type="button">Hover</button>
				</Tooltip>
				<input data-testid="input" />
			</>,
		);

		await user.tab();
		expect(await screen.findByRole('tooltip')).toBeInTheDocument();

		await user.tab();

		expect(screen.getByTestId('input')).toHaveFocus();
		await waitFor(() => expect(screen.queryByRole('tooltip')).not.toBeInTheDocument());
	});

	it('does not steal focus from the trigger when it opens', async () => {
		const user = userEvent.setup();
		render(
			<Tooltip title={TITLE}>
				<button type="button">Hover</button>
			</Tooltip>,
		);

		await user.tab();
		await screen.findByRole('tooltip');

		expect(screen.getByRole('button')).toHaveFocus();
	});
});

describe('Tooltip delay', () => {
	// Real timers: Base UI schedules the open through its own timeout helpers, and
	// faking the clock leaves `user.hover` waiting forever. A slow machine can only
	// make the timer fire later, never earlier, so the early check cannot flake.
	it('waits 300ms on hover by default, so a passing pointer never opens it', async () => {
		const user = userEvent.setup();
		render(
			<Tooltip title={TITLE}>
				<button type="button">Hover</button>
			</Tooltip>,
		);

		await user.hover(screen.getByRole('button'));
		await new Promise((resolve) => setTimeout(resolve, 100));
		expect(screen.queryByRole('tooltip')).not.toBeInTheDocument();

		expect(await screen.findByRole('tooltip')).toBeInTheDocument();
	});

	it('opens at once with delay={0}', async () => {
		const user = userEvent.setup();
		render(
			<TooltipProvider delay={0}>
				<Tooltip title={TITLE}>
					<button type="button">Hover</button>
				</Tooltip>
			</TooltipProvider>,
		);

		await user.hover(screen.getByRole('button'));

		expect(screen.getByRole('tooltip')).toBeInTheDocument();
	});
});

import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it, vi } from 'vitest';
import { Popover } from '../popover.js';
import { usePopoverHandle } from '../use-popover-handle.js';
import { openPopover, renderPopover } from './popover.test-utils.js';

describe('Popover interaction', () => {
	it('opens on a click and closes on the next one', async () => {
		const user = userEvent.setup();
		renderPopover();

		await openPopover();
		await user.click(screen.getByRole('button', { name: 'Open' }));

		await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument());
	});

	it('closes on a press outside', async () => {
		const user = userEvent.setup();
		renderPopover();
		await openPopover();

		await user.click(document.body);

		await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument());
	});

	it('closes on Escape and returns focus to the trigger', async () => {
		const user = userEvent.setup();
		renderPopover({}, <button type="button">Inside</button>);
		await openPopover();

		await user.keyboard('{Escape}');

		await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument());
		expect(screen.getByRole('button', { name: 'Open' })).toHaveFocus();
	});

	it('does not lock the page: the body keeps its scroll and pointer events', async () => {
		renderPopover();
		await openPopover();

		expect(document.body.style.overflow).not.toBe('hidden');
		expect(document.body.style.pointerEvents).not.toBe('none');
	});

	it('reports each change with its reason', async () => {
		const user = userEvent.setup();
		const onOpenChange = vi.fn();
		renderPopover({ onOpenChange });

		await openPopover();
		expect(onOpenChange).toHaveBeenLastCalledWith(
			true,
			expect.objectContaining({ reason: 'trigger-press' }),
		);

		await user.keyboard('{Escape}');
		await waitFor(() =>
			expect(onOpenChange).toHaveBeenLastCalledWith(
				false,
				expect.objectContaining({ reason: 'escape-key' }),
			),
		);
	});

	it('stays open when the close is cancelled through the event details', async () => {
		const user = userEvent.setup();
		renderPopover({
			onOpenChange: (open, details) => {
				if (!open && details.reason === 'outside-press') {
					details.cancel();
				}
			},
		});
		await openPopover();

		await user.click(document.body);

		expect(screen.getByRole('dialog')).toBeInTheDocument();

		await user.keyboard('{Escape}');
		await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument());
	});

	it('is shown and hidden by a handle', async () => {
		function Handled() {
			const handle = usePopoverHandle<string>();

			return (
				<>
					<button type="button" onClick={() => handle.showAt({ x: 40, y: 40 }, 'from state')}>
						Elsewhere
					</button>
					<Popover side="bottom" align="start" handle={handle}>
						{(payload) => <p>{payload}</p>}
					</Popover>
				</>
			);
		}
		const user = userEvent.setup();
		render(<Handled />);

		expect(screen.queryByRole('dialog')).not.toBeInTheDocument();

		await user.click(screen.getByRole('button', { name: 'Elsewhere' }));
		expect(await screen.findByRole('dialog')).toHaveTextContent('from state');

		await user.keyboard('{Escape}');
		await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument());
	});

	it('closes itself through the handle, for a form that just saved', async () => {
		function SaveForm() {
			const handle = usePopoverHandle();

			return (
				<Popover
					nativeButton
					side="bottom"
					align="start"
					handle={handle}
					trigger={<button type="button">Open</button>}
				>
					<button type="button" onClick={() => handle.close()}>
						Save
					</button>
				</Popover>
			);
		}
		const user = userEvent.setup();
		render(<SaveForm />);

		await openPopover();
		await user.click(screen.getByRole('button', { name: 'Save' }));

		await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument());
	});

	it('unmounts the popup on close', async () => {
		const user = userEvent.setup();
		renderPopover();
		await openPopover();

		await user.keyboard('{Escape}');

		await waitFor(() => expect(document.querySelector('[data-slot="popover-popup"]')).toBeNull());
	});
});

import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { useState } from 'react';
import { describe, expect, it, vi } from 'vitest';
import { Checkbox } from '../checkbox.js';

function ControlledCheckbox({ onChange }: { onChange: (checked: boolean) => void }): JSX.Element {
	const [checked, setChecked] = useState(false);

	return (
		<Checkbox
			color="primary"
			value={checked}
			onChange={(next) => {
				setChecked(next);
				onChange(next);
			}}
		>
			Accept the terms
		</Checkbox>
	);
}

describe('Checkbox interaction', () => {
	it('toggles on click and reports the new state', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Checkbox color="primary" onChange={onChange}>
				Accept the terms
			</Checkbox>,
		);

		await user.click(screen.getByRole('checkbox', { name: 'Accept the terms' }));

		expect(onChange).toHaveBeenCalledWith(true);
		expect(screen.getByRole('checkbox')).toBeChecked();
	});

	it('toggles back off', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Checkbox color="primary" defaultValue onChange={onChange}>
				Accept the terms
			</Checkbox>,
		);

		await user.click(screen.getByRole('checkbox'));

		expect(onChange).toHaveBeenCalledWith(false);
		expect(screen.getByRole('checkbox')).not.toBeChecked();
	});

	it('toggles when the label is clicked', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Checkbox color="primary" onChange={onChange}>
				Accept the terms
			</Checkbox>,
		);

		await user.click(screen.getByText('Accept the terms'));

		expect(onChange).toHaveBeenCalledWith(true);
	});

	// The root span carries a 2px hit-area ring around the 16px box, so the pointer target is the
	// whole span, not only the painted box.
	it('toggles from a click on the bare root span, hit area included', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(<Checkbox color="primary" aria-label="Accept the terms" onChange={onChange} />);

		await user.click(screen.getByRole('checkbox'));

		expect(onChange).toHaveBeenCalledWith(true);
		expect(screen.getByRole('checkbox')).toBeChecked();
	});

	// The label wraps the control and Base UI renders a hidden input beside it, which is the
	// classic double-fire shape: the browser forwards a label click to the input while the checkbox
	// handles it too. One user action has to stay one change.
	it('calls onChange once per click, on the checkbox and on the label alike', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Checkbox color="primary" onChange={onChange}>
				Accept the terms
			</Checkbox>,
		);

		await user.click(screen.getByRole('checkbox'));
		expect(onChange).toHaveBeenCalledTimes(1);

		await user.click(screen.getByText('Accept the terms'));
		expect(onChange).toHaveBeenCalledTimes(2);
	});

	it('toggles with Space', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Checkbox color="primary" onChange={onChange}>
				Accept the terms
			</Checkbox>,
		);

		await user.tab();
		expect(screen.getByRole('checkbox')).toHaveFocus();

		await user.keyboard(' ');

		expect(onChange).toHaveBeenCalledWith(true);
		expect(screen.getByRole('checkbox')).toBeChecked();
	});

	// Enter belongs to the form: Base UI submits the owning form instead of toggling, like a
	// native checkbox.
	it('does not toggle on Enter', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Checkbox color="primary" onChange={onChange}>
				Accept the terms
			</Checkbox>,
		);

		await user.tab();
		expect(screen.getByRole('checkbox')).toHaveFocus();

		await user.keyboard('{Enter}');

		expect(onChange).not.toHaveBeenCalled();
		expect(screen.getByRole('checkbox')).not.toBeChecked();
	});

	it('drives a controlled checkbox from its own state', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(<ControlledCheckbox onChange={onChange} />);

		await user.click(screen.getByRole('checkbox'));

		expect(onChange).toHaveBeenCalledWith(true);
		expect(screen.getByRole('checkbox')).toBeChecked();
	});

	it('never moves a controlled checkbox the consumer did not move', async () => {
		const user = userEvent.setup();
		render(
			<Checkbox color="primary" value={false} onChange={() => {}}>
				Accept the terms
			</Checkbox>,
		);

		await user.click(screen.getByRole('checkbox'));

		expect(screen.getByRole('checkbox')).not.toBeChecked();
	});

	it('calls onChange with the checked state alone, not with Base UI event details', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Checkbox color="primary" onChange={onChange}>
				Accept the terms
			</Checkbox>,
		);

		await user.click(screen.getByRole('checkbox'));

		expect(onChange.mock.calls[0]).toEqual([true]);
	});

	// The mixed state is one more value of `value`, so a click still reports the next boolean.
	it('still reports the next boolean while indeterminate', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Checkbox color="primary" value="indeterminate" onChange={onChange}>
				Select all
			</Checkbox>,
		);

		await user.click(screen.getByRole('checkbox'));

		expect(onChange.mock.calls[0]).toEqual([true]);
	});
});

describe('Checkbox disabled', () => {
	it('does not toggle on click', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Checkbox color="primary" disabled disabledTooltip="Ask an admin" onChange={onChange}>
				Accept the terms
			</Checkbox>,
		);

		await user.click(screen.getByRole('checkbox'));

		expect(onChange).not.toHaveBeenCalled();
		expect(screen.getByRole('checkbox')).not.toBeChecked();
	});

	it('does not toggle from the label either', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Checkbox color="primary" disabled disabledTooltip="Ask an admin" onChange={onChange}>
				Accept the terms
			</Checkbox>,
		);

		await user.click(screen.getByText('Accept the terms'));

		expect(onChange).not.toHaveBeenCalled();
	});
});

describe('Checkbox readOnly', () => {
	it('does not toggle on click', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Checkbox
				color="primary"
				defaultValue
				readOnly
				readOnlyTooltip="Saving your changes"
				onChange={onChange}
			>
				Accept the terms
			</Checkbox>,
		);

		await user.click(screen.getByRole('checkbox'));

		expect(onChange).not.toHaveBeenCalled();
		expect(screen.getByRole('checkbox')).toBeChecked();
	});

	it('outranks disabled: the checkbox is locked, not disabled', () => {
		render(
			<Checkbox
				color="primary"
				testId="checkbox"
				aria-label="Accept the terms"
				disabled
				disabledTooltip="Ask an admin"
				readOnly
				readOnlyTooltip="Saving your changes"
			/>,
		);

		const root = screen.getByTestId('checkbox');
		expect(root).not.toHaveAttribute('data-disabled');
		expect(root).not.toHaveAttribute('aria-disabled');
		expect(root).toHaveAttribute('data-readonly');
		expect(root).toHaveAttribute('aria-readonly', 'true');
	});

	it('keeps its tab stop', async () => {
		const user = userEvent.setup();
		render(
			<Checkbox color="primary" readOnly readOnlyTooltip="Saving your changes">
				Accept the terms
			</Checkbox>,
		);

		await user.tab();

		expect(screen.getByRole('checkbox')).toHaveFocus();
	});
});

import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import type { MouseEvent } from 'react';
import { describe, expect, it, vi } from 'vitest';
import { toast } from '../toast.js';
import { Toaster } from '../toaster.js';
import { actionButton, findToast, raise, slot, toasts } from './toast.test-utils.js';

describe('toast action', () => {
	describe('rendering', () => {
		it('is a button named by its label, with its own slot and test id', async () => {
			render(<Toaster testId="my-toaster" />);
			raise(() => toast.success('Saved', { id: 'one', action: { label: 'Undo' } }));

			const action = await screen.findByTestId('my-toaster-toast-one-action');
			expect(action.tagName).toBe('BUTTON');
			expect(action).toHaveAttribute('type', 'button');
			expect(action).toHaveAttribute('data-slot', 'toast-action');
			expect(action).toHaveTextContent('Undo');
			expect(action).toHaveAttribute('data-type', 'success');
		});

		it('takes a ReactNode label', async () => {
			render(<Toaster />);
			raise(() =>
				toast.info('Saved', {
					action: {
						label: (
							<>
								<svg aria-hidden="true" /> Undo
							</>
						),
					},
				}),
			);

			await findToast('Saved');
			expect(actionButton(' Undo')?.querySelector('svg')).not.toBeNull();
		});

		it.each([['success'], ['info'], ['warning'], ['loading']] as const)(
			'is not rendered for %s unless the toast is given one',
			async (variant) => {
				render(<Toaster />);
				raise(() => toast[variant]('Plain'));

				await findToast('Plain');
				expect(slot('toast-action')).toBeNull();
			},
		);

		// The types require an action on danger. Untyped code can still skip it, and there is no
		// default label to fall back to.
		it('is not rendered for a danger toast raised without one', async () => {
			render(<Toaster />);
			raise(() => (toast.danger as (title: string) => string)('Broken'));

			await findToast('Broken');
			expect(slot('toast-action')).toBeNull();
		});

		it('takes the label of the action on a danger toast', async () => {
			render(<Toaster />);
			raise(() => toast.danger('Broken', { action: { label: 'Dismiss' } }));

			await findToast('Broken');
			expect(slot('toast-action')).toHaveTextContent('Dismiss');
		});
	});

	describe('activation', () => {
		it('runs onClick once, then closes the toast', async () => {
			const user = userEvent.setup();
			const onClick = vi.fn();
			render(<Toaster />);
			raise(() => toast.success('Panel deleted', { action: { label: 'Undo', onClick } }));
			await findToast('Panel deleted');

			await user.click(slot('toast-action') as HTMLElement);

			expect(onClick).toHaveBeenCalledOnce();
			await vi.waitFor(() => expect(toasts()).toHaveLength(0));
		});

		it('closes the toast when it has no onClick', async () => {
			const user = userEvent.setup();
			render(<Toaster />);
			raise(() => toast.info('Heads up', { action: { label: 'Cancel' } }));
			await findToast('Heads up');

			await user.click(slot('toast-action') as HTMLElement);

			await vi.waitFor(() => expect(toasts()).toHaveLength(0));
		});

		it('closes a danger toast from its button', async () => {
			const user = userEvent.setup();
			render(<Toaster />);
			raise(() => toast.danger('Broken', { action: { label: 'Close' } }));
			await findToast('Broken');

			await user.click(actionButton('Close') as HTMLElement);

			await vi.waitFor(() => expect(toasts()).toHaveLength(0));
		});

		it('keeps the toast open when onClick calls preventDefault', async () => {
			const user = userEvent.setup();
			const onClick = vi.fn((event: MouseEvent<HTMLButtonElement>) => event.preventDefault());
			render(<Toaster />);
			raise(() => toast.success('Panel deleted', { action: { label: 'Undo', onClick } }));
			await findToast('Panel deleted');

			await user.click(slot('toast-action') as HTMLElement);
			await new Promise((done) => setTimeout(done, 50));

			expect(onClick).toHaveBeenCalledOnce();
			expect(toasts()).toHaveLength(1);

			// The next press without the veto closes it.
			onClick.mockImplementation(() => {});
			await user.click(slot('toast-action') as HTMLElement);
			await vi.waitFor(() => expect(toasts()).toHaveLength(0));
		});

		it('closes only its own toast', async () => {
			const user = userEvent.setup();
			render(<Toaster />);
			raise(() => {
				toast.info('Keep', { action: { label: 'Keep it' } });
				toast.info('Drop', { action: { label: 'Drop it' } });
			});
			await findToast('Drop');

			await user.click(actionButton('Drop it') as HTMLElement);

			await vi.waitFor(() => expect(toasts()).toHaveLength(1));
			expect(slot('toast-title')).toHaveTextContent('Keep');
		});

		it.each([
			['Enter', '{Enter}'],
			['Space', ' '],
		])('fires on %s', async (_name, key) => {
			const user = userEvent.setup();
			const onClick = vi.fn();
			render(<Toaster />);
			raise(() => toast.success('Panel deleted', { action: { label: 'Undo', onClick } }));
			await findToast('Panel deleted');

			slot('toast-action')?.focus();
			await user.keyboard(key);

			expect(onClick).toHaveBeenCalledOnce();
			await vi.waitFor(() => expect(toasts()).toHaveLength(0));
		});
	});
});

import { act, fireEvent, render } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import type { CSSProperties } from 'react';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { Resizable } from '../resizable.js';
import type { ResizableItemType } from '../types.js';
import {
	doubleClick,
	drag,
	Frame,
	handle,
	hover,
	makeItems,
	panelHeight,
	panelWidth,
	releasePointer,
	renderResizable,
	sizeOf,
	TEST_ID,
} from './resizable.test-utils.js';

afterEach(() => {
	releasePointer();
	vi.restoreAllMocks();
});

const BOUNDED: ResizableItemType[] = [
	{ value: 'a', label: 'A', defaultSize: '50%', minSize: '20%', maxSize: '70%', children: 'a' },
	{ value: 'b', label: 'B', children: 'b' },
];

describe('Resizable keyboard', () => {
	it('moves a horizontal handle by 5% with ArrowLeft and ArrowRight', async () => {
		renderResizable({ items: BOUNDED });
		const separator = handle('a');

		separator.focus();
		await userEvent.keyboard('{ArrowRight}');

		expect(sizeOf(separator)).toBe(55);

		await userEvent.keyboard('{ArrowLeft}{ArrowLeft}');

		expect(sizeOf(separator)).toBe(45);
	});

	it('moves a vertical handle with ArrowUp and ArrowDown', async () => {
		renderResizable({ items: BOUNDED, orientation: 'vertical' });
		const separator = handle('a');

		separator.focus();
		await userEvent.keyboard('{ArrowDown}');

		expect(sizeOf(separator)).toBe(55);

		await userEvent.keyboard('{ArrowUp}');

		expect(sizeOf(separator)).toBe(50);
	});

	it('ignores the arrows of the other axis, and keeps them from scrolling the page', () => {
		renderResizable({ items: BOUNDED });
		const separator = handle('a');

		expect(fireEvent.keyDown(separator, { key: 'ArrowUp' })).toBe(false);
		expect(fireEvent.keyDown(separator, { key: 'ArrowDown' })).toBe(false);
		expect(sizeOf(separator)).toBe(50);
	});

	it('moves the handle to the limits with Home and End', async () => {
		renderResizable({ items: BOUNDED });
		const separator = handle('a');

		separator.focus();
		await userEvent.keyboard('{End}');

		expect(sizeOf(separator)).toBe(70);

		await userEvent.keyboard('{Home}');

		expect(sizeOf(separator)).toBe(20);
	});

	it('does nothing on Enter', async () => {
		renderResizable({ items: BOUNDED });
		const separator = handle('a');

		separator.focus();
		await userEvent.keyboard('{Enter}');

		expect(sizeOf(separator)).toBe(50);
	});

	it('cycles the focus through the handles with F6 and Shift+F6', async () => {
		renderResizable({ items: makeItems('a', 'b', 'c') });

		handle('a').focus();
		await userEvent.keyboard('{F6}');

		expect(handle('b')).toHaveFocus();

		await userEvent.keyboard('{F6}');

		expect(handle('a')).toHaveFocus();

		await userEvent.keyboard('{Shift>}{F6}{/Shift}');

		expect(handle('b')).toHaveFocus();
	});

	it('moves the panels on each side of a handle after items change order', () => {
		const { rerender } = render(
			<Frame width={402} height={200}>
				<Resizable testId={TEST_ID} orientation="horizontal" items={makeItems('a', 'b', 'c')} />
			</Frame>,
		);

		rerender(
			<Frame width={402} height={200}>
				<Resizable testId={TEST_ID} orientation="horizontal" items={makeItems('c', 'a', 'b')} />
			</Frame>,
		);
		// Past the panel after it, the handle takes the rest from the next one.
		drag(handle('c'), 300, 0);

		expect(panelWidth('c')).toBeCloseTo(400, 0);
		expect(panelWidth('a')).toBe(0);
		expect(panelWidth('b')).toBe(0);

		drag(handle('a'), -300, 0);

		expect(panelWidth('c')).toBeCloseTo(100, 0);
		expect(panelWidth('b')).toBeCloseTo(300, 0);
	});

	it('cycles the focus through the handles in their new order after items change order', async () => {
		const { rerender } = render(
			<Frame width={400} height={200}>
				<Resizable
					testId={TEST_ID}
					orientation="horizontal"
					items={makeItems('a', 'b', 'c', 'd')}
				/>
			</Frame>,
		);

		rerender(
			<Frame width={400} height={200}>
				<Resizable
					testId={TEST_ID}
					orientation="horizontal"
					items={makeItems('b', 'a', 'c', 'd')}
				/>
			</Frame>,
		);
		handle('b').focus();
		await userEvent.keyboard('{F6}');

		expect(handle('a')).toHaveFocus();

		await userEvent.keyboard('{F6}');

		expect(handle('c')).toHaveFocus();
	});

	it('makes every handle a focus stop in the order of items, and no panel', async () => {
		renderResizable({ items: makeItems('a', 'b', 'c') });

		await userEvent.tab();

		expect(handle('a')).toHaveFocus();

		await userEvent.tab();

		expect(handle('b')).toHaveFocus();
	});
});

describe('Resizable pointer', () => {
	it('grows one panel and shrinks the other by the same amount on a drag', () => {
		renderResizable({ items: makeItems('a', 'b') });
		const before = panelWidth('a') + panelWidth('b');

		drag(handle('a'), 40, 0);

		expect(sizeOf(handle('a'))).toBe(60);
		expect(panelWidth('a') + panelWidth('b')).toBeCloseTo(before, 0);
	});

	it('stops the handle at the limits of the panels', () => {
		renderResizable({ items: BOUNDED });

		drag(handle('a'), 300, 0);

		expect(sizeOf(handle('a'))).toBe(70);

		drag(handle('a'), -400, 0);

		expect(sizeOf(handle('a'))).toBe(20);
	});

	it('drags a vertical handle along the vertical axis', () => {
		renderResizable({ items: makeItems('a', 'b'), orientation: 'vertical' }, { height: 200 });

		drag(handle('a'), 0, -40);

		expect(sizeOf(handle('a'))).toBe(30);
		expect(panelHeight('a')).toBeLessThan(panelHeight('b'));
	});

	it('marks the handle while hovered and while dragged, also with the pointer off the line', () => {
		renderResizable({ items: makeItems('a', 'b') });
		const separator = handle('a');

		hover(separator, 4);

		expect(separator).toHaveAttribute('data-separator', 'hover');

		drag(separator, 120, 0, { release: false });

		expect(separator).toHaveAttribute('data-separator', 'active');
	});

	it('takes the pointer within 5px of the line on each side', () => {
		renderResizable({ items: makeItems('a', 'b') });
		const separator = handle('a');

		hover(separator, 20);

		expect(separator).toHaveAttribute('data-separator', 'inactive');

		hover(separator, -4);

		expect(separator).toHaveAttribute('data-separator', 'hover');
	});
});

describe('Resizable double-click', () => {
	it('puts the panel before the handle back to its defaultSize', () => {
		renderResizable({ items: BOUNDED });

		drag(handle('a'), 60, 0);

		expect(sizeOf(handle('a'))).not.toBe(50);

		doubleClick(handle('a'));

		expect(sizeOf(handle('a'))).toBe(50);
	});

	it('resets the panel after the handle when the one before has no defaultSize', () => {
		renderResizable({
			items: [
				{ value: 'a', label: 'A', children: 'a' },
				{ value: 'b', label: 'B', defaultSize: '30%', children: 'b' },
			],
		});

		drag(handle('a'), -80, 0);
		doubleClick(handle('a'));

		expect(sizeOf(handle('a'))).toBe(70);
	});

	it('does nothing when neither panel has a defaultSize', () => {
		renderResizable({ items: makeItems('a', 'b') });

		drag(handle('a'), 40, 0);
		doubleClick(handle('a'));

		expect(sizeOf(handle('a'))).toBe(60);
	});
});

describe('Resizable handle colour', () => {
	const COLOURS = {
		'--resizable-handle-color': 'rgb(1, 1, 1)',
		'--resizable-handle-active-color': 'rgb(2, 2, 2)',
		'--resizable-handle-transition-duration': '0s',
	} as CSSProperties;

	function renderColoured() {
		render(
			<div style={COLOURS}>
				<Frame width={400} height={200}>
					<Resizable testId={TEST_ID} orientation="horizontal" items={makeItems('a', 'b')} />
				</Frame>
			</div>,
		);
	}

	function colourOf(separator: HTMLElement) {
		return getComputedStyle(separator).backgroundColor;
	}

	it('colours the line while the pointer is in the band', () => {
		renderColoured();

		expect(colourOf(handle('a'))).toBe('rgb(1, 1, 1)');

		hover(handle('a'), 3);

		expect(colourOf(handle('a'))).toBe('rgb(2, 2, 2)');
	});

	it('colours the line of a handle a drag left focused, also under the pointer in the band', () => {
		renderColoured();

		drag(handle('a'), 40, 0);
		hover(handle('a'), 3);

		expect(handle('a')).toHaveFocus();
		expect(colourOf(handle('a'))).toBe('rgb(2, 2, 2)');

		hover(handle('a'), 100);

		expect(colourOf(handle('a'))).toBe('rgb(2, 2, 2)');

		act(() => {
			handle('a').blur();
		});

		expect(colourOf(handle('a'))).toBe('rgb(1, 1, 1)');
	});
});

import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { useState } from 'react';
import { describe, expect, it, vi } from 'vitest';
import { Switch } from '../switch.js';

function ControlledSwitch({ onChange }: { onChange: (checked: boolean) => void }): JSX.Element {
	const [checked, setChecked] = useState(false);

	return (
		<Switch
			color="primary"
			textPlacement="right"
			value={checked}
			onChange={(next) => {
				setChecked(next);
				onChange(next);
			}}
		>
			Wrap text
		</Switch>
	);
}

describe('Switch interaction', () => {
	it('toggles on click and reports the new state', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Switch color="primary" textPlacement="right" onChange={onChange}>
				Wrap text
			</Switch>,
		);

		await user.click(screen.getByRole('switch', { name: 'Wrap text' }));

		expect(onChange).toHaveBeenCalledWith(true);
		expect(screen.getByRole('switch')).toBeChecked();
	});

	it('toggles back off', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Switch color="primary" textPlacement="right" defaultValue onChange={onChange}>
				Wrap text
			</Switch>,
		);

		await user.click(screen.getByRole('switch'));

		expect(onChange).toHaveBeenCalledWith(false);
		expect(screen.getByRole('switch')).not.toBeChecked();
	});

	it('toggles when the label is clicked', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Switch color="primary" textPlacement="right" onChange={onChange}>
				Wrap text
			</Switch>,
		);

		await user.click(screen.getByText('Wrap text'));

		expect(onChange).toHaveBeenCalledWith(true);
	});

	it('toggles when the description is clicked', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Switch
				color="primary"
				textPlacement="right"
				onChange={onChange}
				description="Use the 24-hour convention"
			>
				Display in 24-hour format
			</Switch>,
		);

		await user.click(screen.getByText('Use the 24-hour convention'));

		expect(onChange).toHaveBeenCalledWith(true);
	});

	// The label wraps the control and Base UI renders a hidden input beside it, which is the
	// classic double-fire shape: the browser forwards a label click to the input while the switch
	// handles it too. One user action has to stay one change.
	it('calls onChange once per click, on the switch and on the label alike', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Switch color="primary" textPlacement="right" onChange={onChange}>
				Wrap text
			</Switch>,
		);

		await user.click(screen.getByRole('switch'));
		expect(onChange).toHaveBeenCalledTimes(1);

		await user.click(screen.getByText('Wrap text'));
		expect(onChange).toHaveBeenCalledTimes(2);
	});

	it('toggles with the keyboard', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Switch color="primary" textPlacement="right" onChange={onChange}>
				Wrap text
			</Switch>,
		);

		await user.tab();
		expect(screen.getByRole('switch')).toHaveFocus();

		await user.keyboard(' ');

		expect(onChange).toHaveBeenCalledWith(true);
		expect(screen.getByRole('switch')).toBeChecked();
	});

	it('drives a controlled switch from its own state', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(<ControlledSwitch onChange={onChange} />);

		await user.click(screen.getByRole('switch'));

		expect(onChange).toHaveBeenCalledWith(true);
		expect(screen.getByRole('switch')).toBeChecked();
	});

	it('never moves a controlled switch the consumer did not move', async () => {
		const user = userEvent.setup();
		render(
			<Switch color="primary" textPlacement="right" value={false} onChange={() => {}}>
				Wrap text
			</Switch>,
		);

		await user.click(screen.getByRole('switch'));

		expect(screen.getByRole('switch')).not.toBeChecked();
	});

	it('calls onChange with the checked state alone, not with Base UI event details', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Switch color="primary" textPlacement="right" onChange={onChange}>
				Wrap text
			</Switch>,
		);

		await user.click(screen.getByRole('switch'));

		expect(onChange.mock.calls[0]).toEqual([true]);
	});
});

