describe('ToggleGroup disabled', () => {
	it('blocks one disabled item without taking its events', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<ToggleGroup
				type="single"
				variant="outlined"
				color="secondary"
				size="md"
				defaultValue="logs"
				onChange={onChange}
				items={[
					{ value: 'logs', label: 'Logs' },
					{
						value: 'profiles',
						label: 'Profiles',
						disabled: true,
						disabledTooltip: 'Profiling is not enabled',
					},
				]}
			/>,
		);

		const profiles = screen.getByRole('button', { name: 'Profiles' });

		expect(profiles).toHaveAttribute('aria-disabled', 'true');
		// The native attribute would take every pointer event with it, and the tooltip with them.
		expect(profiles).not.toBeDisabled();

		await user.click(profiles);

		expect(onChange).not.toHaveBeenCalled();
		expect(profiles).toHaveAttribute('aria-pressed', 'false');
	});

	// The two paths reach the button differently: the bar's prop lands as the native attribute, an
	// item's own lands as `aria-disabled`. Only the cursor is asserted, because it is the one value
	// here that is a literal rather than a design token the runner does not load.
	it('marks both disabled paths as blocked rather than clickable', () => {
		render(
			<ToggleGroup
				type="single"
				variant="outlined"
				color="secondary"
				size="md"
				defaultValue="logs"
				items={[
					{ value: 'logs', label: 'Logs' },
					{
						value: 'profiles',
						label: 'Profiles',
						disabled: true,
						disabledTooltip: 'Profiling is not enabled',
					},
				]}
			/>,
		);

		expect(getComputedStyle(screen.getByRole('button', { name: 'Profiles' })).cursor).toBe(
			'not-allowed',
		);
		expect(getComputedStyle(screen.getByRole('button', { name: 'Logs' })).cursor).toBe('pointer');
	});

	it('marks every button of a disabled bar as blocked', () => {
		render(
			<ToggleGroup
				type="single"
				variant="outlined"
				color="secondary"
				size="md"
				items={ITEMS}
				defaultValue="list"
				disabled
				disabledTooltip="This workspace is read only"
			/>,
		);

		for (const button of screen.getAllByRole('button')) {
			expect(getComputedStyle(button).cursor).toBe('not-allowed');
		}
	});

	it('blocks every button while the bar is disabled', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<ToggleGroup
				type="single"
				variant="outlined"
				color="secondary"
				size="md"
				items={ITEMS}
				defaultValue="list"
				onChange={onChange}
				disabled
				disabledTooltip="This workspace is read only"
			/>,
		);

		await user.click(screen.getByRole('button', { name: 'Grid' }));

		expect(onChange).not.toHaveBeenCalled();
	});
});

describe('ToggleGroup readOnly', () => {
	it('holds the value where it is, without calling onChange', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<ToggleGroup
				type="single"
				variant="outlined"
				color="secondary"
				size="md"
				items={ITEMS}
				defaultValue="list"
				onChange={onChange}
				readOnly
				readOnlyTooltip="Saving your changes"
			/>,
		);

		await user.click(screen.getByRole('button', { name: 'Grid' }));

		expect(onChange).not.toHaveBeenCalled();
		expect(screen.getByRole('button', { name: 'List' })).toHaveAttribute('aria-pressed', 'true');
		expect(screen.getByRole('button', { name: 'Grid' })).toHaveAttribute('aria-pressed', 'false');
	});

	// Every button of a locked bar is inert, so Base UI's composite has nowhere to move the arrow
	// keys and holds the roving tab stop on the first one. The reason is the bar's, identical on
	// every button, so that one tab stop is enough to reach it. A disabled bar behaves the same.
	it('keeps its tab stop, and refuses the press that lands on it', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<ToggleGroup
				type="single"
				variant="outlined"
				color="secondary"
				size="md"
				items={ITEMS}
				defaultValue="list"
				onChange={onChange}
				readOnly
				readOnlyTooltip="Saving your changes"
			/>,
		);

		await user.tab();
		expect(screen.getByRole('button', { name: 'List' })).toHaveFocus();

		await user.keyboard('{Enter}');

		expect(onChange).not.toHaveBeenCalled();
		expect(screen.getByRole('button', { name: 'List' })).toHaveAttribute('aria-pressed', 'true');
	});

	it('blocks a multiple bar the same way', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<ToggleGroup
				type="multiple"
				variant="outlined"
				color="secondary"
				size="md"
				items={ITEMS}
				defaultValue={['list']}
				onChange={onChange}
				readOnly
				readOnlyTooltip="Saving your changes"
			/>,
		);

		await user.click(screen.getByRole('button', { name: 'Grid' }));
		await user.click(screen.getByRole('button', { name: 'List' }));

		expect(onChange).not.toHaveBeenCalled();
		expect(screen.getByRole('button', { name: 'List' })).toHaveAttribute('aria-pressed', 'true');
	});

	// The cursor is the one value in the read-only rules that is a literal rather than a design
	// token the runner does not load.
	it('marks every button of a locked bar as blocked', () => {
		render(
			<ToggleGroup
				type="single"
				variant="outlined"
				color="secondary"
				size="md"
				items={ITEMS}
				defaultValue="list"
				readOnly
				readOnlyTooltip="Saving your changes"
			/>,
		);

		for (const button of screen.getAllByRole('button')) {
			expect(getComputedStyle(button).cursor).toBe('not-allowed');
		}
	});
});

import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { useState } from 'react';
import { describe, expect, it, vi } from 'vitest';
import { Tabs } from '../tabs.js';
import type { TabsItemProps } from '../types.js';

const ITEMS: TabsItemProps[] = [
	{ key: 'overview', label: 'Overview', children: 'Overview content' },
	{ key: 'settings', label: 'Settings', children: 'Settings content' },
];

const NAV_ITEMS: TabsItemProps[] = [
	{ key: 'overview', label: 'Overview', render: <a href="#overview" /> },
	{ key: 'logs', label: 'Logs', render: <a href="#logs" /> },
];

/**
 * The outgoing panel stays mounted (`inert`) for its exit transition, which jsdom never runs, so a
 * click can leave two `role="tabpanel"` elements in the DOM. The active one is the one that is not
 * `inert`.
 */
function getActivePanel(): Element | null {
	return document.querySelector('[data-slot="tabs-panel"]:not([inert])');
}

function ControlledTabs({ onChange }: { onChange: (key: string) => void }): JSX.Element {
	const [value, setValue] = useState('overview');

	return (
		<Tabs
			variant="primary"
			orientation="horizontal"
			alignment="start"
			items={ITEMS}
			value={value}
			onChange={(next) => {
				setValue(next);
				onChange(next);
			}}
		/>
	);
}

describe('Tabs interaction', () => {
	it('activates a tab on click and reports its key', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Tabs
				variant="primary"
				orientation="horizontal"
				alignment="start"
				items={ITEMS}
				onChange={onChange}
			/>,
		);

		await user.click(screen.getByRole('tab', { name: 'Settings' }));

		expect(onChange).toHaveBeenCalledWith('settings');
		expect(screen.getByRole('tab', { name: 'Settings' })).toHaveAttribute('data-active');
		await waitFor(() => expect(getActivePanel()).toHaveTextContent('Settings content'));
	});

	it('moves focus with the arrow keys without activating the tab', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Tabs
				variant="primary"
				orientation="horizontal"
				alignment="start"
				items={ITEMS}
				defaultValue="overview"
				onChange={onChange}
			/>,
		);

		await user.tab();
		expect(screen.getByRole('tab', { name: 'Overview' })).toHaveFocus();

		await user.keyboard('{ArrowRight}');

		expect(screen.getByRole('tab', { name: 'Settings' })).toHaveFocus();
		expect(onChange).not.toHaveBeenCalled();
		expect(getActivePanel()).toHaveTextContent('Overview content');
	});

	it('activates the focused tab on Enter', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Tabs
				variant="primary"
				orientation="horizontal"
				alignment="start"
				items={ITEMS}
				defaultValue="overview"
				onChange={onChange}
			/>,
		);

		await user.tab();
		await user.keyboard('{ArrowRight}{Enter}');

		expect(onChange).toHaveBeenCalledWith('settings');
		await waitFor(() => expect(getActivePanel()).toHaveTextContent('Settings content'));
	});

	it('drives a controlled bar from its own state', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(<ControlledTabs onChange={onChange} />);

		await user.click(screen.getByRole('tab', { name: 'Settings' }));

		expect(onChange).toHaveBeenCalledWith('settings');
		await waitFor(() => expect(getActivePanel()).toHaveTextContent('Settings content'));
	});

	it('never moves a controlled bar the consumer did not move', async () => {
		const user = userEvent.setup();
		render(
			<Tabs
				variant="primary"
				orientation="horizontal"
				alignment="start"
				items={ITEMS}
				value="overview"
				onChange={() => {}}
			/>,
		);

		await user.click(screen.getByRole('tab', { name: 'Settings' }));

		expect(screen.getByRole('tab', { name: 'Overview' })).toHaveAttribute('data-active');
		expect(screen.getByRole('tab', { name: 'Settings' })).not.toHaveAttribute('data-active');
	});

	it('calls onChange with the key alone, not with Base UI event details', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Tabs
				variant="primary"
				orientation="horizontal"
				alignment="start"
				items={ITEMS}
				onChange={onChange}
			/>,
		);

		await user.click(screen.getByRole('tab', { name: 'Settings' }));

		expect(onChange.mock.calls[0]).toEqual(['settings']);
	});

	it('starts on the first item when no defaultValue is given', () => {
		render(<Tabs variant="primary" orientation="horizontal" alignment="start" items={ITEMS} />);

		expect(screen.getByRole('tab', { name: 'Overview' })).toHaveAttribute('data-active');
	});

	it('keeps a disabled tab in the arrow-key focus order, same as Button/RadioGroup', async () => {
		const user = userEvent.setup();
		render(
			<Tabs
				variant="primary"
				orientation="horizontal"
				alignment="start"
				defaultValue="overview"
				items={[
					{ key: 'overview', label: 'Overview', children: 'Overview content' },
					{
						key: 'billing',
						label: 'Billing',
						children: 'Billing content',
						disabled: true,
						disabledTooltip: 'Ask an admin',
					},
				]}
			/>,
		);

		await user.tab();
		await user.keyboard('{ArrowRight}');

		// Disabled tabs stay focusable (Base UI `focusableWhenDisabled`), the same guarantee Button
		// relies on for `disabledTooltip`, so the arrow key lands on it rather than skipping it.
		expect(screen.getByRole('tab', { name: 'Billing' })).toHaveFocus();
	});

	it('does not activate a disabled tab on click', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Tabs
				variant="primary"
				orientation="horizontal"
				alignment="start"
				defaultValue="overview"
				onChange={onChange}
				items={[
					{ key: 'overview', label: 'Overview', children: 'Overview content' },
					{
						key: 'billing',
						label: 'Billing',
						children: 'Billing content',
						disabled: true,
						disabledTooltip: 'Ask an admin',
					},
				]}
			/>,
		);

		await user.click(screen.getByRole('tab', { name: 'Billing' }));

		expect(onChange).not.toHaveBeenCalled();
		expect(screen.getByRole('tab', { name: 'Overview' })).toHaveAttribute('data-active');
	});

	it('does not activate a disabled tab on Enter once focused', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Tabs
				variant="primary"
				orientation="horizontal"
				alignment="start"
				defaultValue="overview"
				onChange={onChange}
				items={[
					{ key: 'overview', label: 'Overview', children: 'Overview content' },
					{
						key: 'billing',
						label: 'Billing',
						children: 'Billing content',
						disabled: true,
						disabledTooltip: 'Ask an admin',
					},
				]}
			/>,
		);

		await user.tab();
		await user.keyboard('{ArrowRight}{Enter}');

		expect(onChange).not.toHaveBeenCalled();
		expect(screen.getByRole('tab', { name: 'Overview' })).toHaveAttribute('data-active');
	});

	it('reports the key of a navigating tab that was clicked', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Tabs
				variant="primary"
				orientation="horizontal"
				alignment="start"
				items={NAV_ITEMS}
				value="overview"
				onChange={onChange}
			/>,
		);

		await user.click(screen.getByRole('tab', { name: 'Logs' }));

		expect(onChange).toHaveBeenCalledWith('logs');
		expect(window.location.hash).toBe('#logs');
	});

	it('activates a navigating tab with Space, which an anchor does not do on its own', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		render(
			<Tabs
				variant="primary"
				orientation="horizontal"
				alignment="start"
				items={NAV_ITEMS}
				value="overview"
				onChange={onChange}
			/>,
		);

		await user.tab();
		await user.keyboard('{ArrowRight}[Space]');

		expect(onChange).toHaveBeenCalledWith('logs');
	});

	it('does not follow a disabled navigating tab', async () => {
		const user = userEvent.setup();
		const onChange = vi.fn();
		window.location.hash = '#overview';
		render(
			<Tabs
				variant="primary"
				orientation="horizontal"
				alignment="start"
				value="overview"
				onChange={onChange}
				items={[
					{ key: 'overview', label: 'Overview', render: <a href="#overview" /> },
					{
						key: 'billing',
						label: 'Billing',
						render: <a href="#billing" />,
						disabled: true,
						disabledTooltip: 'Ask an admin',
					},
				]}
			/>,
		);

		await user.click(screen.getByRole('tab', { name: 'Billing' }));

		expect(onChange).not.toHaveBeenCalled();
		expect(window.location.hash).toBe('#overview');
	});

	// The dot is positioned rather than laid out precisely so that this holds. As a flex item it
	// widened the selected tab by its own size plus a gap, which moved every tab after it.
	it('keeps a secondary tab one width whether or not it carries the dot', async () => {
		const user = userEvent.setup();
		render(
			<Tabs
				variant="secondary"
				orientation="horizontal"
				alignment="start"
				items={ITEMS}
				defaultValue="overview"
			/>,
		);

		const settings = screen.getByRole('tab', { name: 'Settings' });
		const label = settings.querySelector<HTMLElement>('[data-slot="tabs-label"]')!;
		const unselectedWidth = settings.getBoundingClientRect().width;
		const unselectedLabelLeft = label.getBoundingClientRect().left;

		await user.click(settings);

		await waitFor(() => {
			expect(settings).toHaveAttribute('data-active');
		});

		const dot = settings.querySelector<HTMLElement>('[data-slot="tabs-dot"]')!;

		expect(getComputedStyle(dot).display).toBe('block');
		expect(getComputedStyle(dot).position).toBe('absolute');
		expect(settings.getBoundingClientRect().width).toBeCloseTo(unselectedWidth, 1);
		expect(label.getBoundingClientRect().left).toBeCloseTo(unselectedLabelLeft, 1);
	});
});

